def txt = { v -> (v == null) ? '' : String.valueOf(v).trim() }
def md5hex = { String s -> java.security.MessageDigest.getInstance('MD5').digest(s.getBytes('UTF-8')).encodeHex().toString() }
// A bulk upsert writes BY ID, so a brand-new record needs one before it exists. Minting
// it from the unique key means the same row uploaded twice targets the same record
// rather than minting a second one -- the idempotency the whole file depends on.
def mint = { String seed -> 'e_' + md5hex(seed).substring(0, 24) }

boolean isDry = (txt(dryRun) == 'true')

// ---- what is already stored, by unique key -------------------------------
def byKey = [:]
(existing ?: []).each { r ->
    def p = r.properties ?: [:]
    String k = txt(p.employeeId).toLowerCase()
    if (k != '') byKey[k] = [id: txt(r.id), props: p]
}

// ---- currency CODE -> entity id ------------------------------------------
// The file carries codes because that is what the export writes and what a person can
// read; the record stores an entity id. Resolved here, once, from one bulk fetch.
def curByCode = [:]
(currencies ?: []).each { c -> def cc = txt((c.properties ?: [:]).code); if (cc != '') curByCode[cc.toLowerCase()] = txt(c.id) }

def parseDay = { String s ->
    if (!(s ==~ /^\d{4}-\d{2}-\d{2}$/)) return -1L
    try { return java.time.LocalDate.parse(s).atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli() }
    catch (Exception e) { return -1L }
}

// A CSV written for Excel carries a BOM, and the reader hands the first header back
// mangled - 'title_code' arrives as '__title_code_'. Normalising every key means the
// template stays Excel-safe without this automation caring how the header was spelled.
def cell = { row, String want ->
    if (row == null) return ''
    def hit = row.find { k, v -> String.valueOf(k).toLowerCase().replaceAll(/[^a-z_]/, '').replaceAll(/^_+|_+$/, '') == want }
    return (hit == null) ? '' : txt(hit.value)
}

def COLUMNS = ["employee_id","first_name","last_name","email","region","business_group","team","status","hire_date","termination_date","payment_currency","personal_currency","personal_target","salary"]

def out = []       // one entry per file row, in file order
def updates = []   // what actually gets written
def seenKey = [:]  // unique key -> the earlier line that already claimed it
int line = 1

(rows ?: []).each { raw ->
    line += 1
    def problems = []
    def rec = [:]
    // employee_id
    def v_employeeId = cell(raw, 'employee_id')
    if (v_employeeId == '') problems << 'employee_id is required'
    rec['employeeId'] = v_employeeId
    // first_name
    def v_firstName = cell(raw, 'first_name')
    if (v_firstName == '') problems << 'first_name is required'
    rec['firstName'] = v_firstName
    // last_name
    def v_lastName = cell(raw, 'last_name')
    rec['lastName'] = v_lastName
    // email
    def v_email = cell(raw, 'email')
    rec['email'] = v_email
    // region
    def v_region = cell(raw, 'region')
    rec['region'] = v_region
    // business_group
    def v_businessGroup = cell(raw, 'business_group')
    rec['businessGroup'] = v_businessGroup
    // team
    def v_team = cell(raw, 'team')
    rec['team'] = v_team
    // status
    def v_status = cell(raw, 'status')
    rec['status'] = v_status
    // hire_date
    def v_hireDate = cell(raw, 'hire_date')
    long ms_hireDate = (v_hireDate == '') ? 0L : parseDay(v_hireDate)
    if (v_hireDate != '' && ms_hireDate < 0) problems << ('hire_date must be yyyy-MM-dd: ' + v_hireDate)
    else if (v_hireDate != '') rec['hireDate'] = ms_hireDate
    // termination_date
    def v_terminationDate = cell(raw, 'termination_date')
    long ms_terminationDate = (v_terminationDate == '') ? 0L : parseDay(v_terminationDate)
    if (v_terminationDate != '' && ms_terminationDate < 0) problems << ('termination_date must be yyyy-MM-dd: ' + v_terminationDate)
    else if (v_terminationDate != '') rec['terminationDate'] = ms_terminationDate
    // payment_currency
    def v_currencyId = cell(raw, 'payment_currency')
    String cid_currencyId = (v_currencyId == '') ? null : curByCode[v_currencyId.toLowerCase()]
    if (v_currencyId == '') problems << 'payment_currency is required'
    if (v_currencyId != '' && cid_currencyId == null) problems << ('payment_currency is not a known currency code: ' + v_currencyId)
    if (cid_currencyId != null) rec['currencyId'] = cid_currencyId
    // personal_currency
    def v_personalCurrencyId = cell(raw, 'personal_currency')
    String cid_personalCurrencyId = (v_personalCurrencyId == '') ? null : curByCode[v_personalCurrencyId.toLowerCase()]
    if (v_personalCurrencyId != '' && cid_personalCurrencyId == null) problems << ('personal_currency is not a known currency code: ' + v_personalCurrencyId)
    if (cid_personalCurrencyId != null) rec['personalCurrencyId'] = cid_personalCurrencyId
    // personal_target
    def v_personalTarget = cell(raw, 'personal_target')
    if (v_personalTarget != '' && v_personalTarget ==~ /^-?\d+(\.\d+)?$/) rec['personalTarget'] = new BigDecimal(v_personalTarget)
    else if (v_personalTarget != '') problems << ('personal_target is not a number: ' + v_personalTarget)
    // salary
    def v_salary = cell(raw, 'salary')
    if (v_salary != '' && v_salary ==~ /^-?\d+(\.\d+)?$/) rec['salary'] = new BigDecimal(v_salary)
    else if (v_salary != '') problems << ('salary is not a number: ' + v_salary)

    String key = txt(rec['employeeId'])
    def prior = seenKey[key.toLowerCase()]
    if (key != '' && prior != null) {
        problems << ('the same employee id appears on line ' + prior + ' of this file')
    } else if (key != '') {
        seenKey[key.toLowerCase()] = line
    }

    // `name` is the object's required nameField and is COMPOSED, never a column. Two
    // writers for one field is how a display name drifts from the boxes producing it.
    String fn = txt(rec['firstName']), ln = txt(rec['lastName'])
    String composed = [fn, ln].findAll { it }.join(' ')
    if (composed != '') rec['name'] = composed

    def hit = (key == '') ? null : byKey[key.toLowerCase()]

    if (!problems.isEmpty()) {
        out << [line: line, raw: raw, key: key, outcome: 'error', reason: problems.join('; ')]
        return
    }

    // UNCHANGED is reported, not written. Re-uploading the template unedited should say
    // "nothing to change" rather than bumping the version of every record in the catalog.
    if (hit != null) {
        boolean same = true
        rec.each { f, v -> if (String.valueOf(hit.props[f] ?: '') != String.valueOf(v ?: '')) same = false }
        if (same) {
            out << [line: line, raw: raw, key: key, outcome: 'unchanged', reason: '']
            return
        }
    }

    String id = (hit != null) ? hit.id : mint('Payee|' + key.toLowerCase())
    // The bulk upsert takes {id, updateFields:[{fieldName, actionType, setValue}]} and
    // NOT a flat property map. A flat map is accepted silently: the node answers
    // success:true with successCount:0 and writes nothing, so the caller is told the
    // file applied and no record moves. Cost one build cycle 2026-09-10.
    //
    // Only the file's own columns are SET, which is also what makes a column the file
    // leaves out keep its stored value: a bulk upload is not a form, so an absent
    // column means "not mentioned", never "clear it".
    def fields = []
    rec.each { f, v -> fields << [fieldName: 'properties.' + f, actionType: 'SET', setValue: v] }
    updates << [id: id, updateFields: fields]
    out << [line: line, raw: raw, key: key, outcome: (hit != null) ? 'updated' : 'created', reason: '']
}

// A file whose header is wrong produces rows with every required cell empty, which reads
// as N identical errors. Naming the missing column once is the difference between a user
// fixing a header and a user re-typing a file.
if (!(rows ?: []).isEmpty()) {
    def firstRow = rows[0]
    def missing = COLUMNS.findAll { c -> (c == 'employee_id') && cell(firstRow, c) == '' && !firstRow.any { k, v -> String.valueOf(k).toLowerCase().replaceAll(/[^a-z_]/, '').replaceAll(/^_+|_+$/, '') == c } }
    if (!missing.isEmpty()) {
        String msg = 'The file is missing the ' + missing.join(' and ') + ' column' + (missing.size() == 1 ? '' : 's') + '.'
        out.each { it.outcome = 'error'; it.reason = msg }
        updates = []
    }
}

int errors = out.count { it.outcome == 'error' }
int changed = out.count { it.outcome == 'created' || it.outcome == 'updated' }
String status
if (out.isEmpty()) status = 'INVALID_INPUT'
else if (errors == out.size()) status = 'REFUSED'
else if (errors > 0) status = 'PARTIAL'
else status = 'APPLIED'

if (isDry) updates = []

// Every row comes back, not just the failures: the result file is the user's own file
// with two columns added, so it can be corrected and re-uploaded whole rather than
// reassembled by hand.
def reported = out.collect { r ->
    def m = [line: r.line, outcome: r.outcome, error: r.reason]
    COLUMNS.each { c -> m[c] = cell(r.raw, c) }
    return m
}

return [status: status, updates: updates, rows: reported,
        applied: changed, written: updates.size(),
        message: isDry ? 'Preview only - nothing was written.' : '']
